import org.apache.commons.lang3.time.DateUtils;
import java.util.*;
import java.text.*;

public class Check {
    public static void main(String[] args) throws Exception {
        TimeZone.setDefault(TimeZone.getTimeZone("America/Los_Angeles"));
        Calendar cal = Calendar.getInstance();
        cal.set(2002, Calendar.JULY, 4, 10, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);

        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd EEE");

        int[] styles = {DateUtils.RANGE_MONTH_SUNDAY, DateUtils.RANGE_MONTH_MONDAY,
            DateUtils.RANGE_WEEK_SUNDAY, DateUtils.RANGE_WEEK_MONDAY,
            DateUtils.RANGE_WEEK_RELATIVE, DateUtils.RANGE_WEEK_CENTER};
        String[] names = {"MONTH_SUNDAY","MONTH_MONDAY","WEEK_SUNDAY","WEEK_MONDAY","WEEK_RELATIVE","WEEK_CENTER"};
        for (int i = 0; i < styles.length; i++) {
            Iterator<Calendar> it = DateUtils.iterator((Calendar) cal.clone(), styles[i]);
            Calendar first = null, last = null;
            int count = 0;
            while (it.hasNext()) {
                Calendar c = it.next();
                if (first == null) first = c;
                last = c;
                count++;
            }
            System.out.println(names[i] + ": first=" + sdf.format(first.getTime()) + " last=" + sdf.format(last.getTime()) + " count=" + count);
        }

        // ceiling / round / truncate on HOUR
        Calendar c2 = Calendar.getInstance();
        c2.set(2002, Calendar.MARCH, 28, 13, 45, 1);
        c2.set(Calendar.MILLISECOND, 231);
        System.out.println("truncate HOUR: " + DateUtils.truncate(c2, Calendar.HOUR_OF_DAY).getTime());
        System.out.println("round HOUR: " + DateUtils.round(c2, Calendar.HOUR_OF_DAY).getTime());
        System.out.println("ceiling HOUR: " + DateUtils.ceiling(c2, Calendar.HOUR_OF_DAY).getTime());

        // parse leniency
        try {
            Date d = DateUtils.parseDate("20230231", "yyyyMMdd");
            System.out.println("lenient parse 20230231 -> " + d);
        } catch (ParseException e) {
            System.out.println("lenient threw: " + e.getMessage());
        }
        try {
            Date d = DateUtils.parseDateStrictly("20230231", "yyyyMMdd");
            System.out.println("strict parse 20230231 -> " + d);
        } catch (ParseException e) {
            System.out.println("strict threw: " + e.getMessage());
        }

        // isSameLocalTime with GregorianCalendar vs another type
        Calendar g1 = Calendar.getInstance();
        Calendar g2 = Calendar.getInstance();
        g1.set(2020,0,1,1,1,1);
        g1.set(Calendar.MILLISECOND,1);
        g2.set(2020,0,1,1,1,1);
        g2.set(Calendar.MILLISECOND,1);
        System.out.println("isSameLocalTime equal cals: " + DateUtils.isSameLocalTime(g1, g2));
    }
}
